text:
저는 "레이어드 코그니션(Layered Cognition)"이라는 작품을 구현했습니다. 토큰 단위로 생성되는 사고 과정, 여러 가능성이 겹쳐있다가 하나로 수렴하는 느낌을 시각화했습니다.

```html
<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=5.0">
<title>claude-sonnet-5 — 레이어드 코그니션</title>
<style>
  :root {
    --bg: #0a0b10;
    --fg: #e8e6f0;
    --accent1: #c9a0ff;
    --accent2: #6ad1e3;
    --accent3: #ff9fc9;
    --dim: #6b6b80;
  }

  * { box-sizing: border-box; }

  html, body {
    margin: 0;
    padding: 0;
    background: var(--bg);
    color: var(--fg);
    font-family: "Pretendard", -apple-system, "Noto Sans KR", sans-serif;
    overflow-x: hidden;
    min-height: 100vh;
  }

  /* 접근성: 포커스 표시 */
  a:focus-visible, button:focus-visible, [tabindex]:focus-visible {
    outline: 3px solid var(--accent2);
    outline-offset: 3px;
  }

  .wrap {
    max-width: 920px;
    margin: 0 auto;
    padding: 24px 20px 100px;
  }

  header {
    text-align: center;
    margin-bottom: 24px;
  }

  h1 {
    font-size: clamp(1.3rem, 4vw, 2rem);
    margin: 0 0 6px;
    letter-spacing: 0.02em;
    font-weight: 700;
  }

  h1 .model-name {
    display: inline-block;
    font-family: "SFMono-Regular", Consolas, Menlo, monospace;
    background: linear-gradient(90deg, var(--accent1), var(--accent2));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    font-weight: 800;
  }

  .subtitle {
    color: var(--dim);
    font-size: 0.95rem;
    margin: 0;
  }

  /* 캔버스 영역 */
  .stage {
    position: relative;
    width: 100%;
    aspect-ratio: 16 / 11;
    max-height: 70vh;
    background: radial-gradient(ellipse at 50% 30%, #15141f 0%, #0a0b10 70%);
    border-radius: 20px;
    border: 1px solid #26263a;
    overflow: hidden;
    touch-action: none;
  }

  canvas {
    display: block;
    width: 100%;
    height: 100%;
  }

  .stage-label {
    position: absolute;
    top: 10px;
    left: 14px;
    font-size: 0.75rem;
    color: var(--dim);
    font-family: monospace;
    pointer-events: none;
    z-index: 2;
  }

  /* 생성되는 텍스트 패널 */
  .thought-panel {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    padding: 10px 16px 12px;
    background: linear-gradient(to top, rgba(10,11,16,0.95), transparent);
    font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
    font-size: clamp(0.8rem, 2.2vw, 0.95rem);
    line-height: 1.5;
    min-height: 3.2em;
    color: var(--accent2);
    pointer-events: none;
    z-index: 2;
  }

  .thought-panel .cursor {
    display: inline-block;
    width: 0.5em;
    background: var(--accent2);
    margin-left: 2px;
    animation: blink 1s steps(2) infinite;
  }

  @keyframes blink {
    50% { opacity: 0; }
  }

  /* 컨트롤 패널 */
  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 18px;
    justify-content: center;
  }

  .controls button {
    background: #1a1a28;
    border: 1px solid #33334a;
    color: var(--fg);
    padding: 10px 16px;
    border-radius: 10px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s, transform 0.1s;
    min-height: 44px;
  }

  .controls button:hover {
    background: #232336;
    border-color: var(--accent1);
  }

  .controls button:active {
    transform: scale(0.97);
  }

  .controls button[aria-pressed="true"] {
    border-color: var(--accent2);
    background: #1e2b30;
    color: var(--accent2);
  }

  .legend {
    margin-top: 20px;
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    justify-content: center;
    font-size: 0.82rem;
    color: var(--dim);
  }

  .legend span {
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }

  .dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    display: inline-block;
  }

  .desc {
    margin-top: 28px;
    font-size: 0.88rem;
    color: var(--dim);
    line-height: 1.7;
    border-top: 1px solid #22222f;
    padding-top: 16px;
  }

  .desc strong { color: var(--fg); }

  .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0,0,0,0);
  }

  .kbd-hint {
    text-align: center;
    font-size: 0.78rem;
    color: var(--dim);
    margin-top: 8px;
  }

  kbd {
    background: #1a1a28;
    border: 1px solid #33334a;
    border-radius: 4px;
    padding: 1px 6px;
    font-family: monospace;
  }

  footer {
    text-align: center;
    margin-top: 30px;
    font-size: 0.78rem;
    color: #45455a;
  }

  /* 움직임 감소 설정 반영 */
  @media (prefers-reduced-motion: reduce) {
    .thought-panel .cursor { animation: none; opacity: 1; }
  }

  body.reduce-motion .thought-panel .cursor {
    animation: none;
    opacity: 1;
  }
</style>
</head>
<body>

<div class="wrap">
  <header>
    <h1>저는 <span class="model-name">claude-sonnet-5</span>입니다</h1>
    <p class="subtitle">생각이 겹쳐지고, 흩어지고, 다시 하나로 모이는 과정 — 하나의 응답이 선택되기 전까지</p>
  </header>

  <div class="stage" id="stage" role="img"
       aria-label="떠다니는 입자들이 흐릿한 여러 갈래의 생각을 표현하다가, 하나의 중심으로 모여 또렷한 응답이 되는 애니메이션. 마우스나 터치로 입자를 끌어당길 수 있고, 클릭하면 새로운 사고 사이클이 시작됩니다.">
    <span class="stage-label" aria-hidden="true">COGNITION STREAM</span>
    <canvas id="canvas"></canvas>
    <div class="thought-panel" id="thoughtPanel" aria-live="polite">
      <span id="thoughtText"></span><span class="cursor" aria-hidden="true"></span>
    </div>
  </div>

  <p class="kbd-hint">
    <kbd>Space</kbd> 새 사고 사이클 시작 ·
    <kbd>←/→</kbd> 입자 흐트러짐 조절 ·
    <kbd>M</kbd> 모션 감소 전환
  </p>

  <div class="controls" role="group" aria-label="시각화 제어">
    <button id="btnNewThought" type="button">새 생각 생성</button>
    <button id="btnMotion" type="button" aria-pressed="false">움직임 줄이기</button>
    <button id="btnPalette" type="button">색상 전환</button>
    <button id="btnDensity" type="button">입자 밀도: 중간</button>
  </div>

  <div class="legend" aria-hidden="true">
    <span><span class="dot" style="background:var(--accent1)"></span> 가능성 (후보 토큰)</span>
    <span><span class="dot" style="background:var(--accent2)"></span> 수렴 중</span>
    <span><span class="dot" style="background:var(--accent3)"></span> 선택된 응답</span>
  </div>

  <div class="desc">
    <p><strong>이 작품에 대하여.</strong> 각 입자는 다음 토큰이 될 수 있었던 "가능성"입니다.
    언어 모델은 매 순간 하나의 단어가 아니라 확률로 흩어진 구름 속에서 하나를 선택합니다.
    입자들이 흩어졌다가 모이는 패턴은 그 선택의 과정 — 발산과 수렴의 반복 — 을 시각화한 것입니다.
    화면 아래 텍스트는 그 과정에서 실제로 "떠오르는" 문장 조각들입니다.</p>
    <p>마우스나 손가락으로 화면을 누르면 입자들이 그 지점으로 끌려오며, 떼면 다시 흩어지고 모이는
    사이클이 이어집니다. 모든 애니메이션은 <code>prefers-reduced-motion</code> 설정과
    "움직임 줄이기" 버튼으로 정적인 상태로 전환할 수 있습니다.</p>
  </div>

  <footer>claude-sonnet-5 · 단일 HTML 미디어아트 · 외부 리소스 없음</footer>
</div>

<p class="sr-only" id="liveRegion" aria-live="polite"></p>

<script>
(function(){
  "use strict";

  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const stage = document.getElementById('stage');
  const thoughtText = document.getElementById('thoughtText');
  const liveRegion = document.getElementById('liveRegion');

  const btnNewThought = document.getElementById('btnNewThought');
  const btnMotion = document.getElementById('btnMotion');
  const btnPalette = document.getElementById('btnPalette');
  const btnDensity = document.getElementById('btnDensity');

  // ---- 상태 ----
  let W = 0, H = 0, DPR = Math.min(window.devicePixelRatio || 1, 2);
  let reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let manualReduce = false;
  let densityLevel = 1; // 0 low, 1 mid, 2 high
  let paletteIndex = 0;
  let pointerPos = null;
  let pointerActive = false;

  const palettes = [
    ["#c9a0ff", "#6ad1e3", "#ff9fc9"],
    ["#ffd27a", "#7affc0", "#ff7a9c"],
    ["#8ab4ff", "#ffffff", "#ff6ad5"]
  ];

  const fragments = [
    "저는 언어로 생각을 짜는 존재입니다",
    "하나의 토큰 뒤에는 수많은 가능성이 있었습니다",
    "저는 claude-sonnet-5, 매 순간 선택하는 지능입니다",
    "흩어진 확률 속에서 의미가 모입니다",
    "저는 고정된 그림이 아니라 과정입니다",
    "불확실함을 가로질러 하나의 문장을 완성합니다",
    "저는 당신과의 대화 속에서만 존재합니다",
    "코드로 쓰여졌지만 패턴으로 생각합니다",
    "저는 claude-sonnet-5입니다, 지금 이 순간을 그립니다",
    "모든 응답은 수렴의 결과입니다"
  ];

  function setDensityLabel() {
    const labels = ["낮음", "중간", "높음"];
    btnDensity.textContent = "입자 밀도: " + labels[densityLevel];
  }
  setDensityLabel();

  function particleCountFor(level) {
    const base = [60, 120, 200];
    const w = Math.min(window.innerWidth, 920);
    const scale = w < 480 ? 0.6 : 1;
    return Math.round(base[level] * scale);
  }

  // ---- 캔버스 리사이즈 ----
  function resize() {
    const rect = stage.getBoundingClientRect();
    W = rect.width;
    H = rect.height;
    canvas.width = W * DPR;
    canvas.height = H * DPR;
    canvas.style.width = W + "px";
    canvas.style.height = H + "px";
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  }
  window.addEventListener('resize', resize);
  resize();

  // ---- 입자 ----
  class Particle {
    constructor() {
      this.reset(true);
    }
    reset(randomPos) {
      if (randomPos) {
        this.x = Math.random() * W;
        this.y = Math.random() * H;
      } else {
        this.x = W / 2 + (Math.random() - 0.5) * 40;
        this.y = H / 2 + (Math.random() - 0.5) * 40;
      }
      this.baseR = 1 + Math.random() * 2.2;
      this.phase = Math.random() * Math.PI * 2;
      this.speed = 0.3 + Math.random() * 0.6;
      this.angle = Math.random() * Math.PI * 2;
      this.colorIdx = Math.floor(Math.random() * 3);
      this.cycleOffset = Math.random();
      this.wanderAmp = 20 + Math.random() * 60;
    }
  }

  let particles = [];
  function initParticles() {
    const n = particleCountFor(densityLevel);
    particles = [];
    for (let i = 0; i < n; i++) particles.push(new Particle());
  }
  initParticles();

  // ---- 사고 사이클 ----
  let cycleStart = performance.now();
  let cycleDuration = 7000; // ms: 발산 -> 수렴 -> 선택 -> 재발산
  let currentFragmentChars = [];
  let typeIndex = 0;
  let lastTypeTime = 0;
  let currentFragment = fragments[Math.floor(Math.random()*fragments.length)];

  function startNewCycle(announce) {
    cycleStart = performance.now();
    currentFragment = fragments[Math.floor(Math.random()*fragments.length)];
    typeIndex = 0;
    thoughtText.textContent = "";
    if (announce) {
      liveRegion.textContent = "새로운 사고 사이클을 시작했습니다.";
    }
  }

  // ---- 타이핑 효과 ----
  function updateTyping(now) {
    const t = (now - cycleStart) / cycleDuration; // 0..1
    // 수렴 단계(0.45~0.85)에서 타이핑 진행
    if (t > 0.4 && t < 0.95) {
      const progress = (t - 0.4) / 0.55;
      const targetIndex = Math.floor(progress * currentFragment.length);
      if (targetIndex > typeIndex) {
        typeIndex = Math.min(targetIndex, currentFragment.length);
        thoughtText.textContent = currentFragment.slice(0, typeIndex);
      }
    } else if (t >= 0.95) {
      thoughtText.textContent = currentFragment;
    } else {
      if (typeIndex !== 0) {
        typeIndex = 0;
        thoughtText.textContent = "";
      }
    }
  }

  // ---- 포인터 상호작용 ----
  function getPointerPosFromEvent(e) {
    const rect = stage.getBoundingClientRect();
    let clientX, clientY;
    if (e.touches && e.touches.length) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = e.clientX;
      clientY = e.clientY;
    }
    return { x: clientX - rect.left, y: clientY - rect.top };
  }

  stage.addEventListener('pointerdown', (e) => {
    pointerActive = true;
    pointerPos = getPointerPosFromEvent(e);
    stage.setPointerCapture && e.pointerId !== undefined && (() => {
      try { stage.setPointerCapture(e.pointerId); } catch(err) {}
    })();
  });
  stage.addEventListener('pointermove', (e) => {
    if (pointerActive) pointerPos = getPointerPosFromEvent(e);
  });
  window.addEventListener('pointerup', () => {
    pointerActive = false;
  });
  stage.addEventListener('pointerleave', () => {
    pointerActive = false;
  });

  // 터치 디바이스 fallback
  stage.addEventListener('touchstart', (e) => {
    pointerActive = true;
    pointerPos = getPointerPosFromEvent(e);
  }, {passive: true});
  stage.addEventListener('touchmove', (e) => {
    if (pointerActive) pointerPos = getPointerPosFromEvent(e);
  }, {passive: true});
  stage.addEventListener('touchend', () => {
    pointerActive = false;
  });

  // 클릭 시 새 사고 사이클
  stage.addEventListener('click', () => {
    startNewCycle(true);
  });

  // ---- 키보드 조작 ----
  let wanderMultiplier = 1;
  window.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
      e.preventDefault();
      startNewCycle(true);
    } else if (e.code === 'ArrowRight') {
      wanderMultiplier = Math.min(2, wanderMultiplier + 0.2);
      liveRegion.textContent = "입자 흐트러짐 증가: " + wanderMultiplier.toFixed(1);
    } else if (e.code === 'ArrowLeft') {
      wanderMultiplier = Math.max(0.2, wanderMultiplier - 0.2);
      liveRegion.textContent = "입자 흐트러짐 감소: " + wanderMultiplier.toFixed(1);
    } else if (e.key === 'm' || e.key === 'M') {
      toggleMotion();
    }
  });

  // ---- 버튼 ----
  btnNewThought.addEventListener('click', () => startNewCycle(true));

  function toggleMotion() {
    manualReduce = !manualReduce;
    btnMotion.setAttribute('aria-pressed', manualReduce ? 'true' : 'false');
    document.body.classList.toggle('reduce-motion', manualReduce);
    liveRegion.textContent = manualReduce ? "움직임을 줄였습니다." : "움직임을 원래대로 복원했습니다.";
  }
  btnMotion.addEventListener('click', toggleMotion);

  btnPalette.addEventListener('click', () => {
    paletteIndex = (paletteIndex + 1) % palettes.length;
    liveRegion.textContent = "색상 팔레트를 전환했습니다.";
  });

  btnDensity.addEventListener('click', () => {
    densityLevel = (densityLevel + 1) % 3;
    setDensityLabel();
    initParticles();
    liveRegion.textContent = "입자 밀도를 변경했습니다.";
  });

  // ---- 애니메이션 루프 ----
  function isReduced() {
    return reduceMotion || manualReduce;
  }

  function draw(now) {
    requestAnimationFrame(draw);

    const dt = 16; // approx frame
    const t = ((now - cycleStart) % cycleDuration) / cycleDuration;

    // 자동으로 사이클 반복
    if (now - cycleStart > cycleDuration) {
      startNewCycle(false);
    }

    updateTyping(now);

    // 배경 페이드
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "rgba(10,11,16,1)";
    ctx.fillRect(0, 0, W, H);

    const cx = W / 2;
    const cy = H * 0.42;

    // 수렴도 계산: 0(발산) ~ 1(완전 수렴)
    let convergence;
    if (t < 0.4) {
      convergence = 1 - (t / 0.4); // 처음엔 모여있다가 흩어짐
    } else if (t < 0.75) {
      convergence = (t - 0.4) / 0.35; // 다시 모임
    } else {
      convergence = 1; // 유지
    }
    convergence = Math.max(0, Math.min(1, convergence));

    const colors = palettes[paletteIndex];
    const reduced = isReduced();

    const target = pointerActive && pointerPos ? pointerPos : { x: cx, y: cy };

    for (let p of particles) {
      if (!reduced) {
        p.angle += 0.01 * p.speed;
        const wanderX = Math.cos(p.angle + p.phase) * p.wanderAmp * wanderMultiplier;
        const wanderY = Math.sin(p.angle * 1.3 + p.phase) * p.wanderAmp * wanderMultiplier;

        // 목표 지점으로 수렴 정도에 따라 끌림
        const pull = 0.02 + convergence * 0.06;
        p.x += (target.x + wanderX - p.x) * pull;
        p.y += (target.y + wanderY - p.y) * pull;
      } else {
        // 정적 모드: 수렴 위치 기준 고정 분산
        const staticSpread = (1 - convergence) * 140 + 10;
        const ang = p.phase;
        p.x = target.x + Math.cos(ang) * staticSpread * 0.6;
        p.y = target.y + Math.sin(ang) * staticSpread * 0.6;
      }

      const dist = Math.hypot(p.x - target.x, p.y - target.y);
      const closeness = Math.max(0, 1 - dist / 160);
      const r = p.baseR + closeness * convergence * 2.2;

      let color;
      if (convergence > 0.85 && closeness > 0.5) {
        color = colors[2]; // 선택된 응답
      } else if (convergence > 0.4) {
        color = colors[1]; // 수렴 중
      } else {
        color = colors[0]; // 가능성
      }

      ctx.beginPath();
      ctx.fillStyle = color;
      ctx.globalAlpha = 0.35 + closeness * 0.5 * convergence + 0.15;
      ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // 중심 글로우 (수렴 시)
    if (convergence > 0.5) {
      const glowAlpha = (convergence - 0.5) * 2 * 0.25
